typedef unsigned char MENU_UINT8;

struct MenuColor
{
	MENU_UINT8 r,g,b,a;
};

class Menu;
class MenuSystem;

class MenuEntry
{
	unsigned int flags;

	public:
	virtual ~MenuEntry() { }
	virtual MenuColor GetColor( void );
};

typedef MenuEntry *pMenuEntry;

class Menu
{
	Menu       *parent;
	int         entries;
	pMenuEntry *entry;
	int         activeentry;
	bool        isopen;
	Menu       *closeto;
	MenuSystem *control;

	public:
	virtual ~Menu();
	MenuColor GetElementColor( int i );
};

extern MenuColor entrydisabled;

MenuColor Menu::GetElementColor( int i )
{
	if (i>=0 && i<entries && entry[i])
		return entry[i]->GetColor();
	else
		return entrydisabled;
}
